-- Generic pinned-source catalog capture. SELECT ONLY; no application rows.
-- Call on the SAME dedicated session with search_path=pg_catalog. No project claim.
with recursive relation_names(name) as (values ('public.research_notification_attempts'),('public.research_notification_outbox'),('quote_delivery_private.qd_directory'),('quote_delivery_private.qd_notification_intents'),('quote_delivery_private.qd_quotes'),('request_intent_private.access_events'),('request_intent_private.catalog_contact_admission'),('request_intent_private.catalog_referral_admission'),('request_intent_private.optional_context'),('request_intent_private.policy_bundles'),('request_intent_private.policy_capture_publications'),('request_intent_private.reported_referral_snapshots'),('request_intent_private.request_policy_snapshots'),('request_intent_private.requests'),('request_intent_private.workflow'),('request_intent_private.workflow_events'),('request_intent_private.workflow_notice_intents'),('request_intent_private.workflow_notice_receipts'),('request_intent_private.workflow_settings'),('request_intent_private.workflow_staff_intents')),
routine_names(name) as (values ('auth.uid'),('public.request_intent_catalog_referral_put'),('public.request_intent_catalog_referral_status'),('public.request_intent_create_with_context'),('public.request_intent_create_with_referral'),('public.request_intent_customer_notice_receipt_record'),('public.request_intent_fixture_mail_disposition'),('public.request_intent_fixture_mail_guard_status'),('public.request_intent_fixture_prepare_metadata'),('public.request_intent_referral_staff_get'),('public.request_intent_staff_get_with_context'),('request_intent_private.capture_request_policy'),('request_intent_private.catalog_address_put'),('request_intent_private.catalog_referral_put'),('request_intent_private.catalog_referral_status'),('request_intent_private.create_or_replay'),('request_intent_private.create_with_context'),('request_intent_private.create_with_referral'),('request_intent_private.customer_notice_receipt_evidence'),('request_intent_private.customer_notice_receipt_record'),('request_intent_private.deny_mutation'),('request_intent_private.enqueue_staff_notices'),('request_intent_private.enqueue_workflow_notice'),('request_intent_private.find_attempt'),('request_intent_private.fixture_admission'),('request_intent_private.fixture_assert_submission'),('request_intent_private.fixture_attempt_fence'),('request_intent_private.fixture_birth'),('request_intent_private.fixture_consume'),('request_intent_private.fixture_control_pin'),('request_intent_private.fixture_has_send_evidence'),('request_intent_private.fixture_job_lineage'),('request_intent_private.fixture_locks'),('request_intent_private.fixture_no_mail_publish'),('request_intent_private.fixture_outbox_fence'),('request_intent_private.fixture_prepare_metadata'),('request_intent_private.fixture_quote_fence'),('request_intent_private.fixture_request_lineage'),('request_intent_private.fixture_snapshot_digest'),('request_intent_private.fixture_workflow_lineage'),('request_intent_private.only_keys'),('request_intent_private.operator_get'),('request_intent_private.policy_capture_initialize_publication'),('request_intent_private.policy_capture_publication_insert'),('request_intent_private.policy_capture_setting_pin'),('request_intent_private.publish_policy_capture_bundle'),('request_intent_private.purge_unmatched_customer_notice_receipts'),('request_intent_private.receipt'),('request_intent_private.referral_staff_get'),('request_intent_private.staff_get'),('request_intent_private.staff_get_with_context'),('request_intent_private.valid_agreements'),('request_intent_private.valid_lines'),('request_intent_private.valid_policy_agreement_pairs'),('request_intent_private.valid_reported_referral'),('request_intent_private.workflow_backend'),('request_intent_private.workflow_customer_notice'),('request_intent_private.workflow_initialize'),('request_intent_private.workflow_setting_pin')),
selected as (select q.name,c.* from relation_names q left join pg_class c on c.oid=to_regclass(q.name)),
role_seeds(oid) as (
 select oid from pg_roles where rolname in ('postgres','anon','authenticated','service_role','ea_quote_stage_runtime','ea_quote_stage_login','supabase_admin','supabase_auth_admin','pg_database_owner')
 union select relowner from selected where oid is not null
 union select p.proowner from pg_proc p join pg_namespace n on n.oid=p.pronamespace join routine_names q on q.name=n.nspname||'.'||p.proname
 union select nspowner from pg_namespace where nspname in ('public','request_intent_private','quote_delivery_private')
 union select evtowner from pg_event_trigger
 union select p.proowner from pg_event_trigger e join pg_proc p on p.oid=e.evtfoid
 union select a.grantee from selected s cross join lateral aclexplode(coalesce(s.relacl,acldefault('r',s.relowner))) a where a.grantee<>0
),
role_closure(oid) as (
 select oid from role_seeds
 union select case when m.member=r.oid then m.roleid else m.member end from pg_auth_members m join role_closure r on m.member=r.oid or m.roleid=r.oid
),
relations as (select s.name,jsonb_build_object(
 'name',s.name,'present',s.oid is not null,'owner',pg_get_userbyid(s.relowner),'kind',s.relkind,'rls',s.relrowsecurity,'forceRls',s.relforcerowsecurity,
 'partition',s.relispartition,'persistence',s.relpersistence,'replicaIdentity',s.relreplident,'options',s.reloptions,
 'inheritance',(select coalesce(jsonb_agg(jsonb_build_array(h.inhrelid::regclass::text,h.inhparent::regclass::text) order by h.inhrelid,h.inhparent),'[]'::jsonb) from pg_inherits h where h.inhrelid=s.oid or h.inhparent=s.oid),
 'acl',(select coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]'::jsonb) from aclexplode(coalesce(s.relacl,acldefault('r',s.relowner))) a),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('number',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,
  'identity',a.attidentity,'generated',a.attgenerated,'dropped',a.attisdropped,'collation',a.attcollation::regcollation::text,'acl',a.attacl::text,
  'defaultSha256',encode(sha256(convert_to(coalesce(pg_get_expr(d.adbin,d.adrelid,false),''),'UTF8')),'hex')) order by a.attnum),'[]'::jsonb) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=s.oid and a.attnum>0),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,'keys',k.conkey,'reference',k.confrelid::regclass::text,'referenceKeys',k.confkey,
  'update',k.confupdtype,'delete',k.confdeltype,'match',k.confmatchtype,'valid',k.convalidated,'deferred',k.condeferred,'deferrable',k.condeferrable,
  'local',k.conislocal,'noInherit',k.connoinherit,'inheritCount',k.coninhcount,'expressionSha256',encode(sha256(convert_to(coalesce(pg_get_expr(k.conbin,k.conrelid,false),''),'UTF8')),'hex')) order by k.conname),'[]'::jsonb) from pg_constraint k where k.conrelid=s.oid),
 'indexes',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'accessMethod',am.amname,'owner',pg_get_userbyid(c.relowner),'unique',i.indisunique,'primary',i.indisprimary,'exclusion',i.indisexclusion,
  'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'immediate',i.indimmediate,'nullsNotDistinct',i.indnullsnotdistinct,'keyCount',i.indnkeyatts,'attributeCount',i.indnatts,
  'keys',i.indkey::text,'options',i.indoption::text,'opclasses',(select jsonb_agg(n.nspname||'.'||o.opcname order by u.ord) from unnest(i.indclass::oid[]) with ordinality u(oid,ord) join pg_opclass o on o.oid=u.oid join pg_namespace n on n.oid=o.opcnamespace),
  'collations',(select jsonb_agg(u.oid::regcollation::text order by u.ord) from unnest(i.indcollation::oid[]) with ordinality u(oid,ord)),
  'expressionSha256',encode(sha256(convert_to(coalesce(pg_get_expr(i.indexprs,i.indrelid,false),''),'UTF8')),'hex'),'predicateSha256',encode(sha256(convert_to(coalesce(pg_get_expr(i.indpred,i.indrelid,false),''),'UTF8')),'hex')) order by c.relname),'[]'::jsonb)
  from pg_index i join pg_class c on c.oid=i.indexrelid join pg_am am on am.oid=c.relam where i.indrelid=s.oid),
 'triggers',(select coalesce(jsonb_agg(item order by item::text),'[]'::jsonb) from (select jsonb_build_object(
  'name',case when t.tgisinternal then null else t.tgname end,'internal',t.tgisinternal,'type',t.tgtype,'enabled',t.tgenabled,'deferred',t.tginitdeferred,'deferrable',t.tgdeferrable,
  'function',n.nspname||'.'||p.proname||'('||replace(oidvectortypes(p.proargtypes),', ',',')||')','arguments',encode(sha256(t.tgargs),'hex'),'argumentCount',t.tgnargs,
  'columnNumbers',t.tgattr::text,'whenSha256',encode(sha256(convert_to(coalesce(t.tgqual::text,''),'UTF8')),'hex'),'definitionSha256',case when t.tgisinternal then null else encode(sha256(convert_to(coalesce(pg_get_triggerdef(t.oid,false),''),'UTF8')),'hex') end,'constraint',k.conname) item
  from pg_trigger t join pg_proc p on p.oid=t.tgfoid join pg_namespace n on n.oid=p.pronamespace left join pg_constraint k on k.oid=t.tgconstraint where t.tgrelid=s.oid) native_triggers),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,
  'roles',(select jsonb_agg(case when u.oid=0 then 'PUBLIC' else pg_get_userbyid(u.oid) end order by case when u.oid=0 then 'PUBLIC' else pg_get_userbyid(u.oid) end) from unnest(p.polroles) u(oid)),
  'usingSha256',encode(sha256(convert_to(coalesce(pg_get_expr(p.polqual,p.polrelid,false),''),'UTF8')),'hex'),'checkSha256',encode(sha256(convert_to(coalesce(pg_get_expr(p.polwithcheck,p.polrelid,false),''),'UTF8')),'hex')) order by p.polname),'[]'::jsonb) from pg_policy p where p.polrelid=s.oid),
 'rules',(select coalesce(jsonb_agg(jsonb_build_array(r.rulename,encode(sha256(convert_to(pg_get_ruledef(r.oid,false),'UTF8')),'hex')) order by r.rulename),'[]'::jsonb) from pg_rewrite r where r.ev_class=s.oid)
 ) item from selected s),
routines as (select n.nspname||'.'||p.proname||'('||replace(replace(oidvectortypes(p.proargtypes),'timestamp with time zone','timestamptz'),', ',',')||')' identity,
 jsonb_build_object('identity',n.nspname||'.'||p.proname||'('||replace(replace(oidvectortypes(p.proargtypes),'timestamp with time zone','timestamptz'),', ',',')||')',
 'owner',pg_get_userbyid(p.proowner),'kind',p.prokind,'language',l.lanname,'securityDefiner',p.prosecdef,'volatility',p.provolatile,'strict',p.proisstrict,'leakproof',p.proleakproof,'parallel',p.proparallel,'returnsSet',p.proretset,
 'arguments',p.proargnames,'argumentModes',p.proargmodes,'result',pg_get_function_result(p.oid),'defaultCount',p.pronargdefaults,'defaultsSha256',encode(sha256(convert_to(coalesce(pg_get_expr(p.proargdefaults,0,false),''),'UTF8')),'hex'),
 'configSha256',encode(sha256(convert_to(coalesce(p.proconfig::text,''),'UTF8')),'hex'),'bodySha256',encode(sha256(convert_to(replace(p.prosrc,chr(13)||chr(10),chr(10)),'UTF8')),'hex'),
 'acl',(select coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]'::jsonb) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a),'effectiveAnon',has_function_privilege('anon',p.oid,'EXECUTE'),'effectiveAuthenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'effectiveService',has_function_privilege('service_role',p.oid,'EXECUTE')) item
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang join routine_names q on q.name=n.nspname||'.'||p.proname)
select jsonb_build_object(
 'identity',jsonb_build_object('pid',pg_backend_pid(),'backendStart',to_char((select backend_start from pg_stat_activity where pid=pg_backend_pid()) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
 'sessionUser',session_user,'currentUser',current_user,'role',current_setting('role'),'version',current_setting('server_version_num')::integer,
 'superuser',(select rolsuper from pg_roles where rolname=current_user),'bypassRls',(select rolbypassrls from pg_roles where rolname=current_user),
 'transactionMs',(select setting::bigint from pg_settings where name='transaction_timeout'),'statementMs',(select setting::bigint from pg_settings where name='statement_timeout'),
 'idleMs',(select setting::bigint from pg_settings where name='idle_in_transaction_session_timeout'),'lockMs',(select setting::bigint from pg_settings where name='lock_timeout')),
 'catalog',jsonb_build_object(
 'relations',(select jsonb_agg(item order by name) from relations),
 'routines',(select coalesce(jsonb_agg(item order by identity),'[]'::jsonb) from routines),
 'schemas',(select jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',(select coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]'::jsonb) from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a)) order by n.nspname) from pg_namespace n where n.nspname in ('public','request_intent_private','quote_delivery_private')),
 'defaults',(select coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype,d.defaclacl::text) order by pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype),'[]'::jsonb) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in ('public','request_intent_private','quote_delivery_private') or (d.defaclnamespace=0 and d.defaclrole in (select oid from role_closure))),
 'roles',(select jsonb_agg(jsonb_build_array(r.rolname,r.rolsuper,r.rolinherit,r.rolcreaterole,r.rolcreatedb,r.rolcanlogin,r.rolreplication,r.rolbypassrls) order by r.rolname) from pg_roles r join role_closure q on q.oid=r.oid),
 'memberships',(select coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(m.roleid),pg_get_userbyid(m.member),pg_get_userbyid(m.grantor),m.admin_option,m.inherit_option,m.set_option) order by pg_get_userbyid(m.roleid),pg_get_userbyid(m.member)),'[]'::jsonb) from pg_auth_members m where m.member in (select oid from role_closure)),
 'extensions',(select coalesce(jsonb_agg(jsonb_build_array(e.extname,e.extversion,n.nspname,pg_get_userbyid(e.extowner),e.extrelocatable) order by e.extname),'[]'::jsonb) from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname in ('pgcrypto','pg_cron','pg_graphql','pg_net')),
 'eventHooks',(select coalesce(jsonb_agg(jsonb_build_object('name',e.evtname,'event',e.evtevent,'enabled',e.evtenabled,'tags',e.evttags,'owner',pg_get_userbyid(e.evtowner),
  'function',n.nspname||'.'||p.proname,'functionOwner',pg_get_userbyid(p.proowner),'securityDefiner',p.prosecdef,'functionAcl',(select coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type),'[]'::jsonb) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a),'currentExecute',has_function_privilege(current_user,p.oid,'EXECUTE'),'schemaUsage',has_schema_privilege(current_user,n.oid,'USAGE'),'definitionSha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')) order by e.evtname),'[]'::jsonb) from pg_event_trigger e join pg_proc p on p.oid=e.evtfoid join pg_namespace n on n.oid=p.pronamespace),
 'sequences',(select coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'acl',(select coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable),'[]'::jsonb) from aclexplode(coalesce(c.relacl,acldefault('S',c.relowner))) a),'start',s.seqstart,'increment',s.seqincrement,'min',s.seqmin,'max',s.seqmax,'cache',s.seqcache,'cycle',s.seqcycle,'parent',d.refobjid::regclass::text,'column',d.refobjsubid) order by n.nspname,c.relname),'[]'::jsonb)
  from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_sequence s on s.seqrelid=c.oid join pg_depend d on d.objid=c.oid and d.deptype in ('a','i') where d.classid='pg_class'::regclass and d.refclassid='pg_class'::regclass and d.refobjid in (select oid from selected)),
 'collisions',(select coalesce(jsonb_agg(item order by item::text),'[]'::jsonb) from (select jsonb_build_array('type',n.nspname,t.typname,t.typtype,pg_get_userbyid(t.typowner)) item from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname||'.'||t.typname in ('request_intent_private.catalog_referral_admission','request_intent_private.optional_context','request_intent_private.policy_bundles','request_intent_private.policy_capture_publications','request_intent_private.reported_referral_snapshots','request_intent_private.request_policy_snapshots','request_intent_private.workflow_notice_receipts') union all select jsonb_build_array('relation',n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','request_intent_private','quote_delivery_private') and (c.relname in ('workflow_notice_receipts_message','research_outbox_fixture_dispatchable_due') or exists(select 1 from relation_names q where q.name in ('request_intent_private.catalog_referral_admission','request_intent_private.optional_context','request_intent_private.policy_bundles','request_intent_private.policy_capture_publications','request_intent_private.reported_referral_snapshots','request_intent_private.request_policy_snapshots','request_intent_private.workflow_notice_receipts') and left(n.nspname||'.'||c.relname,length(q.name))=q.name))) named_collisions)
 )) as evidence;
